package com.zerotrust.internalresource.config; import org.springframework.boot.context.properties.ConfigurationProperties; import java.util.*; @ConfigurationProperties(prefix="security") public class ResourceSecurityProperties { private boolean directAccessEnabled=true; private boolean auditEnabled=true; private String gatewayHeaderName="X-ZT-Gateway"; private String gatewayHeaderValue="zero-trust-rgw"; private List<String> trustedGatewayIps=new ArrayList<>(); public boolean isDirectAccessEnabled(){return directAccessEnabled;} public void setDirectAccessEnabled(boolean v){directAccessEnabled=v;} public boolean isAuditEnabled(){return auditEnabled;} public void setAuditEnabled(boolean v){auditEnabled=v;} public String getGatewayHeaderName(){return gatewayHeaderName;} public void setGatewayHeaderName(String v){gatewayHeaderName=v;} public String getGatewayHeaderValue(){return gatewayHeaderValue;} public void setGatewayHeaderValue(String v){gatewayHeaderValue=v;} public List<String> getTrustedGatewayIps(){return trustedGatewayIps;} public void setTrustedGatewayIps(List<String> v){trustedGatewayIps=v;} }